package com.app.features.promotions.entity;
import com.app.common.BaseEntity;import com.app.features.orders.entity.*;import jakarta.persistence.*;import java.math.BigDecimal;import lombok.Getter;import lombok.Setter;
@Entity @Table(name="order_vouchers",uniqueConstraints=@UniqueConstraint(columnNames={"order_id","voucher_id"})) @Getter @Setter
public class OrderVoucher extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="order_id",nullable=false)private MarketOrder order;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="supplier_order_id")private SupplierOrder supplierOrder;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="voucher_id",nullable=false)private Voucher voucher;@Column(nullable=false,length=80)private String codeSnapshot;@Column(nullable=false,length=20)private String scopeSnapshot;@Column(nullable=false,length=20)private String discountTypeSnapshot;@Column(nullable=false,precision=15,scale=2)private BigDecimal discountValueSnapshot;@Column(nullable=false,precision=15,scale=2)private BigDecimal discountAmount;}
